use super::*;

#[test]
fn derived_catalog_matches_the_language_neutral_oracle_catalog() {
    use semio_framework_pack_json::{JsonMemberPolicy, Value};
    let mutation_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../🏅️standards/7️⃣1.7/🪆️subsets/🧾️vt/🧬️schema/🧬️mutations");
    let manifest = std::fs::read_to_string(mutation_root.join("../../🔮️oracles/🔣️.json")).expect("language-neutral oracle catalog");
    let manifest = semio_framework_pack_json::parse(&manifest, JsonMemberPolicy::Reject).unwrap();
    let catalogs = manifest.get("mutationCatalogs").and_then(Value::as_array).expect("operation catalogs");
    assert_eq!(catalogs.len(), 2);
    let kinds = |catalog: &Value| catalog.get("kinds").and_then(Value::as_array).unwrap().iter().map(|kind| kind.as_str().unwrap().to_string()).collect::<Vec<_>>();
    assert_eq!(kinds(&catalogs[0]), vec!["insert-encryption-dictionary", "remove-encryption-dictionary", "set-output-intent", "remove-output-intent", "set-trim-box", "remove-trim-box", "embed-font-file", "remove-font-file", "insert-javascript-action", "remove-javascript-action", "insert-launch-action", "remove-launch-action", "insert-media-annotation", "remove-media-annotation", "set-dpart-root", "remove-dpart-root", "set-dpart-metadata", "remove-dpart-metadata"].into_iter().map(str::to_string).collect::<Vec<_>>());
    assert_eq!(kinds(&catalogs[1]), vec!["restore-dpart-graph"]);
    assert!(catalogs[1].get("vectors").and_then(Value::as_array).unwrap().is_empty(), "new contract has no invented qualified vectors");
    let declared = catalogs.iter().flat_map(kinds).collect::<Vec<_>>();
    let derived: Vec<&str> = pdf_vt_mutation_kinds().iter().map(|descriptor| descriptor.kind).collect();
    assert_eq!(declared, derived);
    assert_eq!(text::TEXT_OPCODE_REGISTRY.iter().map(|(_, kind)| *kind).collect::<Vec<_>>(), derived);
    assert_eq!(binary::BINARY_TAG_REGISTRY.iter().map(|(_, _, tag)| *tag).collect::<Vec<_>>(), (0..derived.len() as u8).collect::<Vec<_>>());
}
